export function writeSetting(name, value) {
    "use strict";
    if (settings[name] === value) return;
    settings[name] = value;
    if (window.chrome && window.chrome.storage) {
        window.chrome.storage.sync.set(settings);
    } else {
        try {
            localStorage.setItem(name, value);
        } catch (e) {
            handleLocalStorageError(e, "setItem", [name, value]);
        }
    }
}

export function readSetting(name, defaultValue) {
    "use strict";
    let value;
    if ((name in settings) || (window.chrome && window.chrome.storage)) {
        value = settings[name];
    } else {
        try {
            value = localStorage.getItem(name);
        } catch (e) {
            handleLocalStorageError(e, "getItem", [name]);
        }
        settings[name] = value;
    }
    if (typeof value === "undefined") {
        value = null;
    }

    if (value === null && typeof defaultValue !== "undefined") {
        return defaultValue;
    }

    return value;
}

export function eraseSetting(name) {
    "use strict";
    // Deleting here means that next time the setting is read when using local
    // storage, it will be pulled from local storage again.
    // If the setting in local storage is changed (e.g. in another tab)
    // between this delete and the next read, it could lead to an unexpected
    // value change.
    delete settings[name];
    if (window.chrome && window.chrome.storage) {
        window.chrome.storage.sync.remove(name);
    } else {
        try {
            localStorage.removeItem(name);
        } catch (e) {
            handleLocalStorageError(e, "removeItem", [name]);
        }
    }
}

let localStorageWarned = false;

function handleLocalStorageError(e, func, args) {
    if (!(e instanceof DOMException)) {
        throw e;
    }
    if (!localStorageWarned) {
        Log.Warn("Couldn't access noVNC settings, are cookies disabled?");
        localStorageWarned = true;
    }
    Log.Debug("'localStorage." + func + "(" + args.join(",") + ")' failed: " + e);
}

